    "css": ".clear {\n  clear: both;\n}\n\n.checkBox {\n  display: block;\n  cursor: pointer;\n  width: 30px;\n  height: 30px;\n  border: 3px solid rgba(255, 255, 255, 0);\n  border-radius: 10px;\n  position: relative;\n  overflow: hidden;\n  box-shadow: 0px 0px 0px 2px #fff;\n}\n\n.checkBox div {\n  width: 60px;\n  height: 60px;\n  background-color: #fff;\n  top: -52px;\n  left: -52px;\n  position: absolute;\n  transform: rotateZ(45deg);\n  z-index: 100;\n}\n\n.checkBox input[type=checkbox]:checked + div {\n  left: -10px;\n  top: -10px;\n}\n\n.checkBox input[type=checkbox] {\n  position: absolute;\n  left: 50px;\n  visibility: hidden;\n}\n\n.transition {\n  transition: 300ms ease;\n}"
