    "css": ".absolute {\n  position: absolute;\n}\n.relative {\n  position: relative;\n}\n.left-0 {\n  left: 0px;\n}\n.top-1\\/2 {\n  top: 50%;\n}\n.flex {\n  display: flex;\n}\n.h-\\[2em\\] {\n  height: 2em;\n}\n.w-\\[2em\\] {\n  width: 2em;\n}\n.-translate-x-full {\n  --tw-translate-x: -100%;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y))\n    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))\n    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));\n}\n.-translate-y-1\\/2 {\n  --tw-translate-y: -50%;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y))\n    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))\n    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));\n}\n.cursor-pointer {\n  cursor: pointer;\n}\n.appearance-none {\n  -webkit-appearance: none;\n  appearance: none;\n}\n.items-center {\n  align-items: center;\n}\n.justify-center {\n  justify-content: center;\n}\n.gap-\\[1em\\] {\n  gap: 1em;\n}\n.rounded-\\[0\\.25em\\] {\n  border-radius: 0.25em;\n}\n.border-\\[2px\\] {\n  border-width: 2px;\n}\n.border-\\[\\#80FF00\\] {\n  --tw-border-opacity: 1;\n  border-color: rgb(128 255 0 / var(--tw-border-opacity));\n}\n.text-\\[1em\\] {\n  font-size: 1em;\n}\n.font-semibold {\n  font-weight: 600;\n}\n.text-\\[\\#80FF00\\] {\n  --tw-text-opacity: 1;\n  color: rgb(128 255 0 / var(--tw-text-opacity));\n}\n.duration-500 {\n  transition-duration: 500ms;\n}\n.ease-out {\n  transition-timing-function: cubic-bezier(0, 0, 0.2, 1);\n}\n.\\[stroke-dasharray\\:100\\] {\n  stroke-dasharray: 100;\n}\n.\\[stroke-dashoffset\\:100\\] {\n  stroke-dashoffset: 100;\n}\n.\\[user-select\\:none\\] {\n  -webkit-user-select: none;\n  user-select: none;\n}\n.peer:checked ~ .peer-checked\\:\\[stroke-dashoffset\\:0\\] {\n  stroke-dashoffset: 0;\n}\n"
